import XCTest
import CryptoKit
@testable import BlockleProtect

/// Proves the Swift PQ core reproduces the audited TS core byte-for-byte, using
/// golden-vectors.json generated by packages/core/scripts/golden.ts. If any of
/// these fail, a proof made on iOS would NOT verify in the browser — so this is
/// the cross-platform contract gate.
final class CryptoVectorsTests: XCTestCase {
    var v: [String: Any]!

    override func setUpWithError() throws {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "golden-vectors", withExtension: "json"))
        v = try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any]
    }

    private func sub(_ k: String) -> [String: Any] { v[k] as! [String: Any] }

    func testSHA384() {
        let g = sub("sha384")
        let out = ProtectCrypto.sha384(Data((g["input_utf8"] as! String).utf8))
        XCTAssertEqual(out.hex, g["output_hex"] as! String)
    }

    func testHKDFSHA384() {
        let g = sub("hkdfSha384")
        let out = ProtectCrypto.hkdfSha384(
            ikm: Data(hex: g["ikm_hex"] as! String)!,
            salt: Data((g["salt_utf8"] as! String).utf8),
            info: Data((g["info_utf8"] as! String).utf8),
            length: g["length"] as! Int)
        XCTAssertEqual(out.hex, g["output_hex"] as! String)
    }

    func testAESGCM() throws {
        let g = sub("aesGcm")
        let out = try ProtectCrypto.aesGcmEncrypt(
            key: Data(hex: g["key_hex"] as! String)!,
            nonce: Data(hex: g["nonce_hex"] as! String)!,
            plaintext: Data((g["plaintext_utf8"] as! String).utf8),
            aad: Data((g["aad_utf8"] as! String).utf8))
        XCTAssertEqual(out.hex, g["ciphertext_and_tag_hex"] as! String)
    }

    func testCanonicalJSON() {
        let g = sub("canonicalJson")
        let value = JSONValueBridge.from(g["value"]!)
        let s = CanonicalJSON.string(value)
        XCTAssertEqual(s, g["canonical_string"] as! String)
        XCTAssertEqual(ProtectCrypto.sha384(Data(s.utf8)).hex, g["canonical_sha384_hex"] as! String)
    }

    func testMerkle() {
        let g = sub("merkle")
        let commitments = (g["commitments_hex"] as! [String]).map { Data(hex: $0)! }
        XCTAssertEqual(Merkle.hashLeaf(commitments[1]).hex, g["leaf1_hex"] as! String)
        XCTAssertEqual(Merkle.root(commitments).hex, g["root_hex"] as! String)
    }

    func testMLDSAVerifyGoldenSignature() throws {
        try requireIOS26()
        guard #available(iOS 26.0, macOS 26.0, *) else { return }
        let g = sub("mldsa65")
        let ok = ProtectCrypto.PQ.dsaVerify(
            publicKey: Data(hex: g["publicKey_hex"] as! String)!,
            message: Data((g["message_utf8"] as! String).utf8),
            signature: Data(hex: g["signature_hex"] as! String)!)
        XCTAssertTrue(ok, "TS-produced ML-DSA-65 signature must verify in CryptoKit")
    }

    func testMLDSAKeygenFromSeedMatches() throws {
        try requireIOS26()
        guard #available(iOS 26.0, macOS 26.0, *) else { return }
        let g = sub("mldsa65")
        let (pub, _) = try ProtectCrypto.PQ.dsaKeygenFromSeed(Data(hex: g["seed32_hex"] as! String)!)
        XCTAssertEqual(pub.hex, g["publicKey_hex"] as! String, "seed→ML-DSA pubkey must match the TS core")
    }

    func testMLKEMKeygenAndDecapsulateMatch() throws {
        try requireIOS26()
        guard #available(iOS 26.0, macOS 26.0, *) else { return }
        let g = sub("mlkem768")
        let (pub, sk) = try ProtectCrypto.PQ.kemKeygenFromSeed(Data(hex: g["seed64_hex"] as! String)!)
        XCTAssertEqual(pub.hex, g["publicKey_hex"] as! String, "seed→ML-KEM pubkey must match the TS core")
        let ss = try ProtectCrypto.PQ.kemDecapsulate(cipherText: Data(hex: g["cipherText_hex"] as! String)!, privateKey: sk)
        XCTAssertEqual(ss.hex, g["sharedSecret_hex"] as! String, "decapsulating the TS cipherText must recover the same shared secret")
    }

    /// Full round trip: protect a file on iOS, then verify its signed manifest +
    /// commitment + a Merkle inclusion proof the way the web verifier would.
    func testProtectRoundTrip() throws {
        try requireIOS26()
        guard #available(iOS 26.0, macOS 26.0, *) else { return }
        let seed = Data((0..<64).map { UInt8(($0 * 11 + 2) & 0xff) })
        let (kemPub, kemSk) = try ProtectCrypto.PQ.kemKeygenFromSeed(seed)
        let dseed = Data((0..<32).map { UInt8(($0 * 13 + 5) & 0xff) })
        let (dsaPub, dsaSk) = try ProtectCrypto.PQ.dsaKeygenFromSeed(dseed)
        let plaintext = Data("Blockle Protect — iOS round trip".utf8)

        let r = try Protector.protect(
            plaintext: plaintext,
            recipients: [Recipient(kemPublicKey: kemPub, kind: "device")],
            signerPublicKey: dsaPub, signerPrivateKey: dsaSk, label: "report.txt", now: 1_700_000_000)

        // signature verifies over the canonical manifest bytes
        XCTAssertTrue(ProtectCrypto.PQ.dsaVerify(
            publicKey: dsaPub, message: r.signed.manifest.signingBytes,
            signature: Data(base64url: r.signed.signature)!))
        // commitment is a SHA-384 and resolves to a single-leaf Merkle root
        let commitment = r.signed.commitment
        XCTAssertEqual(commitment.count, 48)
        XCTAssertEqual(Merkle.root([commitment]).hex, Merkle.hashLeaf(commitment).hex)
        _ = kemSk
    }

    /// A file protected by the TS core to a seeded recipient must UNPROTECT on
    /// iOS — proves cross-platform secure sharing (web/backend → iOS).
    func testUnprotectCrossPlatform() throws {
        try requireIOS26()
        guard #available(iOS 26.0, macOS 26.0, *) else { return }
        let g = sub("envelope")
        let (pub, sk) = try ProtectCrypto.PQ.kemKeygenFromSeed(Data(hex: g["kemSeed64_hex"] as! String)!)
        let signed = try JSONDecoder().decode(SignedManifest.self, from: Data((g["signedManifestJson"] as! String).utf8))
        let holder = Protector.Holder(kemPrivateKey: sk, recipientId: recipientIdFor(pub))
        XCTAssertEqual(holder.recipientId, g["recipientId"] as! String, "recipientId derivation must match TS")
        let pt = try Protector.unprotect(ciphertext: Data(hex: g["ciphertext_hex"] as! String)!,
                                         manifest: signed.manifest, holder: holder)
        XCTAssertEqual(String(data: pt, encoding: .utf8), g["plaintext_utf8"] as! String,
                       "a TS-protected file must open on iOS")
    }

    private func requireIOS26() throws {
        if #available(iOS 26.0, macOS 26.0, *) { return }
        throw XCTSkip("Post-quantum tests require iOS/macOS 26+")
    }
}

/// Converts Foundation-parsed JSON into our JSONValue so the canonical
/// serializer can be tested against any value shape.
enum JSONValueBridge {
    static func from(_ any: Any) -> JSONValue {
        switch any {
        case let s as String: return .string(s)
        case let n as NSNumber:
            if CFGetTypeID(n) == CFBooleanGetTypeID() { return .bool(n.boolValue) }
            return .int(n.intValue)
        case let a as [Any]: return .array(a.map { from($0) })
        case let d as [String: Any]: return .object(d.map { ($0.key, from($0.value)) })
        case is NSNull: return .null
        default: return .null
        }
    }
}
